C("rabies", "Rabies", SYS, "kritis", "Riwayat gigitan hewan: hidrofobia, aerofobia, agitasi, hipersalivasi. Fatal; profilaksis pascapajanan.")
C("ramsay_hunt", "Sindrom Ramsay Hunt (herpes zoster otikus)", SYS, "sedang", "Paresis N. VII perifer disertai vesikel di telinga/liang telinga dan nyeri telinga hebat.")
C("neuritis_vestibular", "Neuritis vestibular", SYS, "sedang", "Vertigo berat terus-menerus berhari-hari tanpa gangguan dengar, sering pascainfeksi virus.")
C("penyakit_meniere", "Penyakit Ménière", SYS, "sedang", "Serangan vertigo berjam-jam dengan tinitus, telinga penuh, dan tuli sensorineural fluktuatif.")
